                    rev: { terra: 0, dist: 0, pest: 0, yield: 0, v2: 0 },
                    deal: null,
                    alliance: null,
                    plan: null,
                    flags: {},
                    revenueHistory: [BASE_REV],
                    riskHistory: [70],
                    pipelineHistory: [30]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._bindLanguage();
            this._updateBriefing(state);
            this._renderProjects(state.domainState);
        }

        _bindLanguage() {
            if (this._langBound) return;
            this._langBound = true;
            var self = this;
            var repaint = function () {
                try {
                    var st = window.mySimulation && window.mySimulation.state;
                    if (!st) return;
                    self._renderBriefingText(st.currentPeriod || 1);
                    self._renderProjects(st.domainState || {});
                    var cm = document.getElementById('usf-completion-content') || document.getElementById('completionContent');
                    if (cm && cm.querySelector('.agritech-cm') && st.history && st.history.length) {
                        cm.innerHTML = self.formatCompletionMessage(self.getPerformanceSummary(st.history));
                    }
                } catch (e) {}
            };
            document.addEventListener('express:langchanged', function () { setTimeout(repaint, 0); });
            try {
                if (window.mySimulation && window.mySimulation.eventBus && window.mySimulation.eventBus.on) {
                    window.mySimulation.eventBus.on('language:changed', function () { setTimeout(repaint, 0); });
                }
            } catch (e) {}
        }

        _roundIndex(period) {
            return Math.min(Math.max((period || 1) - 1, 0), this.ROUND_KEYS.length - 1);
        }

        _renderBriefingText(period) {
            var key = this.ROUND_KEYS[this._roundIndex(period)];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl) { titleEl.setAttribute('data-i18n', key + '_title'); titleEl.textContent = this._t(key + '_title'); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.setAttribute('data-i18n', key + '_brief'); briefEl.textContent = this._t(key + '_brief'); }
        }

        _updateBriefing(state) {
            this._renderBriefingText(state.currentPeriod || 1);
            this._renderDecisionControls(state.currentPeriod || 1, state.domainState);
        }

        _stratKey(project, value) {
            if (!value) return 'strat_pending';
            return 'strat_' + project + '_' + value;
        }

        _renderProjects(ds) {
            var grid = document.getElementById('projectsGrid');
            if (!grid || !ds) return;
            var self = this;
            var card = function (nameKey, statKey, project, value) {
                var sk = self._stratKey(project, value);
                return '<div class="agritech-innovation-project-card">' +
                    '<div class="agritech-innovation-project-name" data-i18n="' + nameKey + '">' + self._t(nameKey) + '</div>' +
                    '<div class="agritech-innovation-project-stats"><span data-i18n="' + statKey + '">' + self._t(statKey) + '</span><br>' +
                    '<span data-i18n="current_strategy">' + self._t('current_strategy') + '</span> ' +
                    '<strong data-i18n="' + sk + '">' + self._t(sk) + '</strong></div></div>';
            };
            grid.innerHTML = card('proj_terra_name', 'proj_terra_stats', 'terra', ds.terraStrategy) +
                card('proj_pest_name', 'proj_pest_stats', 'pest', ds.pestStrategy) +
                card('proj_yield_name', 'proj_yield_stats', 'yield', ds.yieldStrategy);
            var pipeEl = document.getElementById('pipelineDisplay');
            if (pipeEl) pipeEl.textContent = Math.round(ds.pipeline != null ? ds.pipeline : 30) + '/100';
        }

        _group(id, labelKey, inner, hintKey) {
            var h = '<div class="agritech-innovation-form-group">';
            h += '<label for="' + id + '" data-i18n="' + labelKey + '">' + this._t(labelKey) + '</label>';
            h += inner;
            if (hintKey) h += '<div class="agritech-innovation-hint" id="' + id + 'Hint" data-i18n="' + hintKey + '">' + this._t(hintKey) + '</div>';
            h += '</div>';
            return h;
        }

        _select(id, opts, hintKey) {
            var self = this;
            var h = '<select id="' + id + '"' + (hintKey ? ' aria-describedby="' + id + 'Hint"' : '') + '>';
            opts.forEach(function (o) { h += '<option value="' + o[0] + '" data-i18n="' + o[1] + '">' + self._t(o[1]) + '</option>'; });
            return h + '</select>';
        }

        _number(id, min, max, step, value, hintKey) {
            return '<input type="number" id="' + id + '" min="' + min + '" max="' + max + '" step="' + step + '" value="' + value + '"' +
                (hintKey ? ' aria-describedby="' + id + 'Hint"' : '') + '>';
        }

        _renderDecisionControls(period, ds) {
            var container = document.getElementById('decisionControls');
            if (!container) return;
            var html = '';
            if (period === 1) {
                html += this._group('terraStrategy', 'dec1_terra_label', this._select('terraStrategy', [
                    ['internal', 'opt_terra_internal'], ['license', 'opt_terra_license'],
                    ['designaround', 'opt_terra_design'], ['abandon', 'opt_terra_abandon']], 'dec1_terra_hint'), 'dec1_terra_hint');
                html += this._group('pestStrategy', 'dec1_pest_label', this._select('pestStrategy', [
                    ['internal', 'opt_pest_internal'], ['university', 'opt_pest_uni'],
                    ['license3rd', 'opt_pest_license'], ['abandon', 'opt_pest_abandon']], 'dec1_pest_hint'), 'dec1_pest_hint');
                html += this._group('yieldStrategy', 'dec1_yield_label', this._select('yieldStrategy', [
                    ['internal', 'opt_yield_internal'], ['analytics', 'opt_yield_partner'],
                    ['abandon', 'opt_yield_abandon']], 'dec1_yield_hint'), 'dec1_yield_hint');
            } else if (period === 2) {
                html += this._group('licenseUpfront', 'dec2_upfront_label', this._number('licenseUpfront', 10, 100, 1, 50, 'dec2_upfront_hint'), 'dec2_upfront_hint');
                html += this._group('licenseRoyalty', 'dec2_royalty_label', this._number('licenseRoyalty', 10, 25, 1, 20, 'dec2_royalty_hint'), 'dec2_royalty_hint');
                html += this._group('futureAccess', 'dec2_access_label', this._select('futureAccess', [
                    ['yes', 'opt_access_yes'], ['no', 'opt_access_no']], 'dec2_access_hint'), 'dec2_access_hint');
                html += this._group('exclusivity', 'dec2_distribution_label', this._select('exclusivity', [
                    ['yes', 'opt_excl_yes'], ['no', 'opt_excl_no']], 'dec2_distribution_hint'), 'dec2_distribution_hint');
            } else if (period === 3) {
                html += this._group('zamoranoFunding', 'dec3_funding_label', this._number('zamoranoFunding', 100, 300, 10, 250, 'dec3_funding_hint'), 'dec3_funding_hint');
                html += this._group('ipOwnership', 'dec3_ip_label', this._select('ipOwnership', [
                    ['coowner', 'opt_ip_co'], ['agrotech', 'opt_ip_agro'], ['zamorano', 'opt_ip_zam']]), null);
                html += this._group('commercialRights', 'dec3_commercial_label', this._select('commercialRights', [
                    ['exclusive5', 'opt_excl_5'], ['exclusive3', 'opt_excl_3'], ['nonexclusive', 'opt_non_excl']]), null);
                html += this._group('pubRights', 'dec3_publication_label', this._select('pubRights', [
                    ['delayed', 'opt_pub_delayed'], ['immediate', 'opt_pub_imm'], ['none', 'opt_pub_none']]), null);
            } else {
                html += this._group('terra2Invest', 'dec4_terra2_label', this._select('terra2Invest', [
                    ['150', 'opt_terra2_yes'], ['0', 'opt_terra2_no']]), null);
                html += this._group('blockchainInvest', 'dec4_blockchain_label', this._select('blockchainInvest', [
                    ['100', 'opt_block_yes'], ['50', 'opt_block_pilot'], ['0', 'opt_block_no']]), null);
                html += this._group('revenueTarget', 'dec4_target_label', this._number('revenueTarget', 4, 10, 0.1, 6.5, 'dec4_target_hint'), 'dec4_target_hint');
            }
            html += '<div id="decisionError" class="agritech-innovation-error" role="alert" aria-live="assertive"></div>';
            container.innerHTML = html;
        }

        _readNumber(id, min, max) {
            var el = document.getElementById(id);
            if (!el) return null;
            var v = parseFloat(String(el.value).replace(',', '.'));
            if (!isFinite(v) || v < min || v > max) return NaN;
            return v;
        }

        _showError(key, vars) {
            var el = document.getElementById('decisionError');
            if (el) el.textContent = key ? this._t(key, vars) : '';
        }

        validateDecisions(decisions) {
            // read the controls as the student left them; never re-render inside validation (EQIL 14 item 11, W6)
            var period = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.currentPeriod) || 1;
            var self = this;
            var sel = function (id) { var el = document.getElementById(id); return el ? el.value : ''; };
            var bad = null;
            if (period === 1) {
                decisions.terraStrategy = sel('terraStrategy');
                decisions.pestStrategy = sel('pestStrategy');
                decisions.yieldStrategy = sel('yieldStrategy');
            } else if (period === 2) {
                var up = this._readNumber('licenseUpfront', 10, 100);
                var roy = this._readNumber('licenseRoyalty', 10, 25);
                if (up !== null && isNaN(up)) bad = ['err_range', { min: 10, max: 100 }];
                if (roy !== null && isNaN(roy)) bad = ['err_range', { min: 10, max: 25 }];
                decisions.licenseUpfront = up;
                decisions.licenseRoyalty = roy;
                decisions.futureAccess = sel('futureAccess');
                decisions.exclusivity = sel('exclusivity');
            } else if (period === 3) {
                var f = this._readNumber('zamoranoFunding', 100, 300);
                if (f !== null && isNaN(f)) bad = ['err_range', { min: 100, max: 300 }];
                decisions.zamoranoFunding = f;
                decisions.ipOwnership = sel('ipOwnership');
                decisions.commercialRights = sel('commercialRights');
                decisions.pubRights = sel('pubRights');
            } else {
                var t = this._readNumber('revenueTarget', 4, 10);
                if (t !== null && isNaN(t)) bad = ['err_range', { min: 4, max: 10 }];
                decisions.terra2Invest = parseInt(sel('terra2Invest'), 10);
                decisions.blockchainInvest = parseInt(sel('blockchainInvest'), 10);
                decisions.revenueTarget = t;
            }
            if (bad) { self._showError(bad[0], bad[1]); return false; }
            self._showError(null);
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                budget: r.budget,
                legalRisk: r.legalRisk,
                activeProjects: r.activeProjects,
                expectedRevenue: r.expectedRevenue,
                pipeline: r.pipeline,
                overallScore: r.score,
                score: r.score
            };
        }

        _engagement(funding) {
            return 1 - Math.exp(-(funding - 50) / 55);
        }

        _projected(ds) {
            var p = ds.rev || {};
            return BASE_REV + (p.terra || 0) + (p.dist || 0) + (p.pest || 0) + (p.yield || 0) + (p.v2 || 0);
        }

        _computeRound(state) {
            var d = state.decisions || {};
            var ds = state.domainState;
            var period = state.currentPeriod;
            var fl = ds.flags = ds.flags || {};
            ds.rev = ds.rev || { terra: 0, dist: 0, pest: 0, yield: 0, v2: 0 };

            if (period === 1) {
                ds.terraStrategy = d.terraStrategy || 'internal';
                ds.pestStrategy = d.pestStrategy || 'internal';
                ds.yieldStrategy = d.yieldStrategy || 'internal';
                if (ds.terraStrategy === 'internal') {
                    ds.budget -= 200000; ds.legalRisk = 85; ds.rev.terra = TERRA_GROSS;
                } else if (ds.terraStrategy === 'license') {
                    ds.budget -= 20000; ds.legalRisk = 40; ds.rev.terra = TERRA_GROSS * 0.80;
                } else if (ds.terraStrategy === 'designaround') {
                    ds.budget -= 300000; ds.legalRisk = 35; ds.rev.terra = 0.70;
                } else {
                    ds.legalRisk = 10; ds.rev.terra = 0; ds.activeProjects -= 1; ds.pipeline -= 10;
                }
                if (ds.pestStrategy === 'internal') {
                    ds.budget -= 250000; ds.rev.pest = 0.15;
                } else if (ds.pestStrategy === 'university') {
                    ds.rev.pest = 0.10; ds.pipeline += 5;
                } else if (ds.pestStrategy === 'license3rd') {
                    ds.budget -= 150000; ds.rev.pest = 0.30; ds.pipeline -= 5; ds.legalRisk += 5;
                } else {
                    ds.rev.pest = 0; ds.activeProjects -= 1; ds.pipeline -= 10;
                }
                if (ds.yieldStrategy === 'internal') {
                    ds.budget -= 150000; ds.rev.yield = 0.30; ds.pipeline += 5;
                } else if (ds.yieldStrategy === 'analytics') {
                    ds.budget -= 90000; ds.rev.yield = 0.30; ds.pipeline -= 10; ds.legalRisk += 5;
                } else {
                    ds.rev.yield = 0; ds.activeProjects -= 1; ds.pipeline -= 10;
                }
            } else if (period === 2) {
                var up = (d.licenseUpfront != null && isFinite(d.licenseUpfront)) ? d.licenseUpfront : 50;
                var roy = (d.licenseRoyalty != null && isFinite(d.licenseRoyalty)) ? d.licenseRoyalty : 20;
                var access = d.futureAccess === 'yes';
                var excl = d.exclusivity === 'yes';
                var path = ds.terraStrategy;
                var threshold = LIC_BASE + (access ? 1.5 : 0) - (excl ? 1 : 0) +
                    (path === 'internal' ? 4 : 0) - (path === 'designaround' ? 3 : 0) - (path === 'abandon' ? 2 : 0);
                var ask = roy + up / 10;
                var accepted = ask >= threshold;
                ds.deal = { upfront: up, royalty: roy, access: access, exclusive: excl, accepted: accepted, threshold: threshold, ask: ask };
                fl.firstOffer = accepted && up >= 50 && roy >= 20;
                fl.dealRejected = !accepted;
                if (accepted) {
                    ds.budget -= up * 1000;
                    if (path === 'internal') { ds.legalRisk = 30; ds.rev.terra = TERRA_GROSS * (1 - roy / 100); fl.settlement = true; }
                    else if (path === 'license') { ds.legalRisk = 5; ds.rev.terra = TERRA_GROSS * (1 - roy / 100); }
                    else if (path === 'designaround') { ds.legalRisk = 5; ds.rev.terra = 0.70 * (1 - roy / 100); fl.paidTwice = true; }
                    else { ds.legalRisk = 5; ds.budget -= 60000; ds.rev.terra = 0.50 * (1 - roy / 100); ds.activeProjects += 1; }
                    ds.rev.dist = excl ? DIST_REV : 0;
                } else {
                    if (path === 'internal') { ds.legalRisk = 90; ds.budget -= 150000; fl.sued = true; }
                    else if (path === 'license') { ds.legalRisk = 25; ds.rev.terra = 0.40 * 0.80; fl.launchStalled = true; }
                    ds.rev.dist = 0;
                }
            } else if (period === 3) {
                var f = (d.zamoranoFunding != null && isFinite(d.zamoranoFunding)) ? d.zamoranoFunding : 250;
                var ip = d.ipOwnership || 'coowner';
                var comm = d.commercialRights || 'exclusive5';
                var pub = d.pubRights || 'delayed';
                var fit = ds.pestStrategy === 'university' ? 1 : (ds.pestStrategy === 'license3rd' ? 0.3 : 0.5);
                var e = this._engagement(f);
                if (ip === 'agrotech' && f < 250) e *= 0.85;
                if (pub === 'none') {
                    e = 0; ds.pipeline -= 5; fl.uniWalked = true;
                    if (ds.pestStrategy === 'university') { ds.rev.pest = 0; ds.activeProjects -= 1; fl.pestStalled = true; }
                }
                if (pub === 'immediate') { ds.pipeline -= 10; ds.legalRisk += 5; fl.pubImmediate = true; }
                if (ip === 'coowner') ds.legalRisk += 3;
                if (ip === 'zamorano') ds.pipeline -= 3;
                var commMult = comm === 'exclusive5' ? 1 : (comm === 'exclusive3' ? 0.95 : 0.75);
                if (comm === 'exclusive5') ds.pipeline += 5; else if (comm === 'exclusive3') ds.pipeline += 2;
                fl.underfunded = (pub !== 'none' && f < 150);
                if (pub !== 'none') ds.budget -= f * 1000;
                ds.rev.pest = (ds.rev.pest || 0) + 0.25 * e * commMult * fit;
                ds.pipeline += 15 * e * fit;
                if (ds.pestStrategy === 'abandon' && e > 0) { ds.activeProjects += 1; }
                ds.alliance = { funding: f, ip: ip, comm: comm, pub: pub, engagement: Math.round(e * 100) / 100 };
            } else {
                var v2 = parseInt(d.terra2Invest, 10) || 0;
                var bc = parseInt(d.blockchainInvest, 10) || 0;
                var deal = ds.deal || {};
                ds.budget -= v2 * 1000;
                ds.budget -= bc * 1000;
                if (v2 > 0) {
                    if (deal.accepted && deal.access) { ds.pipeline += 25; ds.rev.v2 = 0.10; }
                    else if (deal.accepted) { ds.pipeline += 12; ds.rev.v2 = 0.05; fl.v2NoAccess = true; }
                    else { ds.pipeline += 3; ds.rev.v2 = 0; ds.legalRisk += 5; fl.v2NoDeal = true; }
                }
                if (bc >= 100) ds.pipeline += 14; else if (bc >= 50) ds.pipeline += 12;
                fl.noRoadmap = (v2 === 0 && bc === 0);
                var target = (d.revenueTarget != null && isFinite(d.revenueTarget)) ? d.revenueTarget : 6.5;
                ds.plan = { terra2: v2, blockchain: bc, target: target };
            }

            ds.legalRisk = Math.max(0, Math.min(100, ds.legalRisk));
            ds.pipeline = Math.max(0, Math.min(100, ds.pipeline));
            ds.expectedRevenue = Math.round(this._projected(ds) * 100) / 100;
            if (ds.plan) {
                var gap = ds.plan.target - ds.expectedRevenue;
                fl.overcommit = gap > 0.3;
                fl.sandbag = gap < -1.0;
            }
            fl.overspent = ds.budget < 0;
            ds.revenueHistory.push(ds.expectedRevenue);
            ds.riskHistory.push(ds.legalRisk);
            (ds.pipelineHistory = ds.pipelineHistory || [30]).push(Math.round(ds.pipeline));

            var sc = this._computeScore(ds);
            ds.performance = { overallScore: sc.total, grade: sc.band, outcome: sc.outcome, process: sc.process };
            ds.performanceTier = sc.band;
            ds.score = sc.total;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({currentPeriod: __eqilNext, domainState: ds});
                self._renderProjects(ds);
            })(state.currentPeriod + 1), 500);

            return { period: period, budget: ds.budget, legalRisk: ds.legalRisk, activeProjects: ds.activeProjects,
                expectedRevenue: ds.expectedRevenue, pipeline: Math.round(ds.pipeline), score: sc.total };
        }

        /* One function for score, sub-scores, band and label (G-D).
           Revenue 2027 net of royalties 30, legal exposure 30, innovation portfolio 25,
           budget discipline 10, credibility of the committed target 5. */
        _computeScore(ds) {
            ds = ds || {};
            var rev = ds.expectedRevenue != null ? ds.expectedRevenue : BASE_REV;
            var risk = ds.legalRisk != null ? ds.legalRisk : 70;
            var pipe = ds.pipeline != null ? ds.pipeline : 30;
            var budget = ds.budget != null ? ds.budget : 600000;
            var parts = {
                revenue: Math.max(0, Math.min(1, (rev - BASE_REV) / 2.0)) * 30,
                legal: (100 - risk) / 100 * 30,
                portfolio: Math.max(0, Math.min(100, pipe)) / 100 * 25,
                budget: budget >= 0 ? 10 : Math.max(0, 10 + budget / 25000),
                credibility: 5
            };
            if (ds.plan) {
                var gap = ds.plan.target - rev;
                if (gap > 0.3) parts.credibility = Math.max(0, 5 - (gap - 0.3) * 5);
                else if (gap < -1.0) parts.credibility = Math.max(0, 5 - (-gap - 1.0) * 5);
            }
            var total = Math.round(Math.max(0, Math.min(100,
                parts.revenue + parts.legal + parts.portfolio + parts.budget + parts.credibility)));
            // bands from the sweep: expert play 96, random players median 57 and p90 65
            var band = total >= 90 ? 'excellent' : (total >= 75 ? 'good' : (total >= 60 ? 'adequate' : 'needs_work'));
            return {
                total: total, band: band, parts: parts,
                outcome: Math.round((parts.revenue + parts.legal) / 60 * 100),
                process: Math.round((parts.portfolio + parts.budget + parts.credibility) / 40 * 100)
            };
        }

        _mistakes(ds) {
            var fl = ds.flags || {};
            var deal = ds.deal || {};
            var out = [];
            if (ds.terraStrategy === 'internal') out.push({ key: fl.sued ? 'mk_internal_sued' : 'mk_internal_settled', loss: fl.sued ? 40 : 20 });
            if (ds.terraStrategy === 'designaround') out.push({ key: fl.paidTwice ? 'mk_design_twice' : 'mk_design', loss: 12 });
            if (ds.terraStrategy === 'abandon') out.push({ key: 'mk_terra_abandon', loss: 12 });
            if (fl.firstOffer) out.push({ key: 'mk_first_offer', loss: 4 });
            if (fl.dealRejected && ds.terraStrategy !== 'internal') out.push({ key: 'mk_deal_rejected', loss: 10 });
            if (fl.uniWalked) out.push({ key: 'mk_uni_walked', loss: 11 });
            else if (fl.underfunded) out.push({ key: 'mk_underfunded', loss: 6 });
            if (fl.pubImmediate) out.push({ key: 'mk_pub_immediate', loss: 5 });
            if (ds.yieldStrategy === 'analytics') out.push({ key: 'mk_yield_partner', loss: 6 });
            if (ds.pestStrategy === 'abandon' || ds.yieldStrategy === 'abandon') out.push({ key: 'mk_abandon_core', loss: 7 });
            if (fl.noRoadmap) out.push({ key: 'mk_no_roadmap', loss: 10 });
            if (fl.v2NoDeal) out.push({ key: 'mk_v2_nodeal', loss: 4 });
            else if (fl.v2NoAccess) out.push({ key: 'mk_v2_noaccess', loss: 3 });
            if (fl.overspent) out.push({ key: 'mk_overspent', loss: Math.min(10, -ds.budget / 25000) });
            if (fl.overcommit) out.push({ key: 'mk_overcommit', loss: 3 });
            if (fl.sandbag) out.push({ key: 'mk_sandbag', loss: 2 });
            if (deal.accepted && deal.royalty > 20) out.push({ key: 'mk_high_royalty', loss: 3 });
            out.sort(function (a, b) { return b.loss - a.loss; });
            return out;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var final = last.results || {};
            var sc = this._computeScore(ds);
            var self = this;
            var mk = this._mistakes(ds);
            var insights = [];
            var deal = ds.deal || {};
            var vars = {
                rev: this._fmtM(ds.expectedRevenue || BASE_REV), risk: Math.round(ds.legalRisk || 0),
                roy: deal.royalty, up: deal.upfront, pipe: Math.round(ds.pipeline || 0),
                budget: this._fmtK(ds.budget || 0), target: ds.plan ? this._fmtM(ds.plan.target) : '-',
                fund: ds.alliance ? ds.alliance.funding : '-'
            };
            insights.push(this._t('ins_result', vars));
            if (deal.accepted) insights.push(this._t('ins_deal_signed', vars));
            mk.slice(0, 4).forEach(function (m) { insights.push(self._t(m.key, vars)); });
            if (!mk.length) insights.push(this._t('ins_clean', vars));
            var turning = mk.length ? this._t(mk[0].key + '_tp') : this._t('tp_none');
            return {
                score: sc.total,
                overallScore: sc.total,
                totalScore: sc.total,
                composite: sc.total,
                outcomeScore: sc.outcome,
                processScore: sc.process,
                parts: sc.parts,
                finalRevenue: final.expectedRevenue,
                finalRisk: final.legalRisk,
                remainingBudget: final.budget,
                activeProjects: final.activeProjects,
                pipeline: Math.round(ds.pipeline || 0),
                performance: sc.band,
                performanceKey: 'band_' + sc.band,
                performanceLabel: this._t('band_' + sc.band),
                turningPoint: turning,
                mistakes: mk.map(function (m) { return m.key; }),
                insights: insights,
                questions: [this._t('q1'), this._t('q2'), this._t('q3')],
                totalPeriods: history.length
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = this._t.bind(this);
            var esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var p = summary.parts || {};
            var r1 = function (v) { return Math.round((v || 0) * 10) / 10; };
            var h = '<div class="agritech-cm" role="region" aria-label="' + esc(t('cm_title')) + '">';
            h += '<h3 class="agritech-cm-title">' + esc(t('cm_title')) + '</h3>';
            h += '<div class="agritech-cm-score"><span class="agritech-cm-num">' + esc(summary.score) + '</span>/100 · <strong>' + esc(summary.performanceLabel) + '</strong></div>';
            h += '<ul class="agritech-cm-kpis">';
            h += '<li>' + esc(t('cm_k_revenue')) + ': USD ' + esc(this._fmtM(summary.finalRevenue || BASE_REV)) + 'M</li>';
            h += '<li>' + esc(t('cm_k_risk')) + ': ' + esc(summary.finalRisk) + '%</li>';
            h += '<li>' + esc(t('cm_k_pipeline')) + ': ' + esc(summary.pipeline) + '/100</li>';
            h += '<li>' + esc(t('cm_k_budget')) + ': ' + esc(this._fmtK(summary.remainingBudget || 0)) + '</li>';
            h += '</ul>';
            h += '<p class="agritech-cm-sub">' + esc(t('cm_outcome')) + ': ' + esc(summary.outcomeScore) + '/100 · ' + esc(t('cm_process')) + ': ' + esc(summary.processScore) + '/100</p>';
            h += '<p class="agritech-cm-sub">' + esc(t('cm_parts', { a: r1(p.revenue), b: r1(p.legal), c: r1(p.portfolio), d: r1(p.budget), e: r1(p.credibility) })) + '</p>';
            h += '<h4>' + esc(t('cm_turning')) + '</h4><p>' + esc(summary.turningPoint) + '</p>';
            h += '<h4>' + esc(t('cm_insights')) + '</h4><ul>';
            (summary.insights || []).forEach(function (s) { h += '<li>' + esc(s) + '</li>'; });
            h += '</ul><h4>' + esc(t('cm_questions')) + '</h4><ol>';
            (summary.questions || []).forEach(function (s) { h += '<li>' + esc(s) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            if (ds.legalRisk > 80) return this._t('hint_high_legal');
            if (ds.budget < 0) return this._t('hint_low_budget');
            return null;
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget', function(v) { return self._fmtK(v); });
            uiManager.bind('riskDisplay', 'domainState.legalRisk', function(v) {
                var w = v < 30 ? self._t('risk_low') : (v < 60 ? self._t('risk_mid') : self._t('risk_high'));
                var bar = document.getElementById('riskBar');
                if (bar) bar.style.width = Math.max(0, Math.min(100, v)) + '%';
                return w + ' (' + Math.round(v) + '%)';
            });
            uiManager.bind('projectsDisplay', 'domainState.activeProjects');
            uiManager.bind('revenueDisplay', 'domainState.expectedRevenue', function(v) { return 'USD ' + self._fmtM(v) + 'M'; });
            uiManager.bind('pipelineDisplay', 'domainState.pipeline', function(v) { return Math.round(v) + '/100'; });
        }

