        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var rh = ds.revenueHistory || [];
            var kh = ds.riskHistory || [];
            var labels = rh.map(function(_, i) { return i === 0 ? 'P0' : 'P' + i; });
            return { portfolioChart: { labels: labels, datasets: [ { data: rh }, { data: kh } ] } };
        }

